import {bannerFields} from './commerce.js';
import {recordActions} from './management.js';
import {themeSettings,loginSettings,aiSettings} from './engagement.js';
import {teamEditor} from './editors.js';
import {E,money,icon,button,link,field,select,textarea,checkbox,table,stat,badge,notice,heading,tabs,previewBar,wordmark} from './ui.js';
import {seoModules} from './data.js';
export function seoView(s,tab){const values=s.saved['seo-'+tab]||{};let content='';if(tab==='overview')content=`<div class="stats">${stat('Products',s.products.length,'Catalogue metadata')}${stat('Published pages',3,'Sample public pages')}${stat('Redirects',s.records.redirects.length,'Internal redirects')}${stat('Needs review',3,'Sample warnings')}</div><div class="card"><h3>SEO readiness</h3>${[['Set the canonical store domain','The preview uses an example origin.','global'],['Review product descriptions','Replace the sample product copy before launch.','products'],['Configure search verification','No external service is connected.','verification']].map(([a,b,t])=>link(`<div><strong>${a}</strong><p class="small muted">${b}</p></div>${icon('chevron')}`,'/admin/seo/'+t,'list-link')).join('')}</div><div class="card"><h3>Explore SEO modules</h3><div class="module-grid">${seoModules.slice(1).map(([id,t])=>link(t,'/admin/seo/'+id,'list-link')).join('')}</div></div>`;
else if(tab==='redirects')content=`<div class="between mb"><h3>Redirect rules</h3>${button('Add redirect','new-record','data-type="redirects"','btn small')}</div>${table(['From','To','Status','Actions'],s.records.redirects.filter(r=>!r.archived).map(r=>[E(r.from),E(r.to),r.type,recordActions(s,'redirects',r.id)]))}<div class="notice mt">Self redirects, duplicates and loops are rejected. Rules here only update the preview dataset.</div>`;
else if(tab==='sitemap')content=`<div class="card"><div class="between"><h3>Sitemap preview</h3>${button('Download sample XML','sitemap-download','','btn small secondary')}</div><p class="small muted mb">Published, indexable canonical records only.</p>${table(['Path','Source','State'],[['/','Homepage','Eligible'],...s.products.map(p=>['/product/'+p.id,'Product','Eligible']),...s.records.pages.filter(p=>p.status==='Published').map(p=>['/'+p.id,'CMS','Eligible'])])}<p class="form-help">The live preview is private and noindex. This is a proposed production sitemap list, not a submitted sitemap.</p></div>`;
else if(tab==='robots')content=`<form class="card" data-form="config" data-section="seo-robots"><h3>Robots & indexing</h3>${notice('Staging protection is enabled for this preview. Changes below are draft configuration only.')}${textarea('Production robots.txt draft','robots',values.robots||'User-agent: *\nDisallow: /admin/\nDisallow: /account/\nDisallow: /checkout/\nDisallow: /install/','class="code-area"')}${select('Default content indexing','indexing',['index, follow','noindex, follow','noindex, nofollow'],values.indexing||'index, follow')}${checkbox('Keep staging environments noindex','staging',true)}<div class="error-text" data-error></div><button class="btn">Save draft</button><p class="form-help">robots.txt is not an access-control mechanism. Private routes require server authorization.</p></form>`;
else if(tab==='schema')content=`<form class="card" data-form="config" data-section="seo-schema"><h3>Structured data</h3>${['Organization','WebSite','Product','BreadcrumbList','FAQPage'].map(x=>checkbox(x,x,values[x]??true)).join('')}${textarea('Organization name','organization',values.organization||'AELVO Fashion')}${notice('Product price, stock and reviews must come from actual published records. Do not fabricate ratings or FAQ content.')}<div class="form-actions"><button class="btn">Save draft</button></div></form><div class="card"><h3>Example JSON-LD</h3><pre class="code-area" style="white-space:pre-wrap">${E(JSON.stringify({'@context':'https://schema.org','@type':'Organization',name:values.organization||'AELVO Fashion'},null,2))}</pre></div>`;
else if(tab==='verification')content=`<form class="card" data-form="config" data-section="seo-verification"><h3>Site verification</h3>${field('Google Search Console token','google',values.google||'','text','placeholder="Verification token"')}${field('Bing Webmaster token','bing',values.bing||'')}${field('Other approved verification token','other',values.other||'')}${notice('Enter tokens only, not arbitrary scripts. Saving a token does not verify ownership with a provider.')}<div class="form-actions"><button class="btn">Save draft</button></div></form>`;
else if(tab==='analytics')content=analyticsForm(s,'seo-analytics');
else if(tab==='errors')content=`<div class="card"><h3>404 monitor</h3>${table(['Path','Count','First seen','Last seen',''],[['/old-collection',12,'01 Oct','07 Oct',button('Create redirect','new-record','data-type="redirects" data-from="/old-collection"','text-link')],['/summer-edit',4,'05 Oct','07 Oct',button('Create redirect','new-record','data-type="redirects" data-from="/summer-edit"','text-link')]])}<p class="form-help">Illustrative log entries. Sensitive query values must be redacted in the backend.</p></div>`;
else {const entity=tab==='products'?s.products[0]?.name:tab==='categories'?'Shoes':tab==='brands'?'AELVO':tab==='cms'?'The Footwear Edit':tab==='homepage'?'Homepage':'Global defaults';const title=values.title||((tab==='global'||tab==='homepage')?'AELVO Fashion · Everyday Essentials':entity+' | AELVO');const desc=values.description||'Explore considered shoes, bags and accessories for everyday life.';content=`<form data-form="config" data-section="seo-${tab}" class="two-col"><div class="card"><h3>${E(entity)}</h3>${['products','categories','brands','cms'].includes(tab)?select('Content record','entity',tab==='products'?s.products.map(p=>p.name):tab==='categories'?['Shoes','Bags','Wallets','Socks','Belts']:tab==='brands'?['AELVO']:s.records.pages.map(p=>p.name),values.entity||entity):''}${field('SEO title','title',title,'text','data-seo-live="title" maxlength="160"')}${textarea('Meta description','description',desc,'data-seo-live="description" maxlength="320"')}${tab==='global'?field('Canonical base URL','base','https://aelvo.example','url')+field('Title template','template',values.template||'{page_title} | AELVO')+field('Legacy meta keywords (optional)','keywords',values.keywords||''):tab==='homepage'?field('Homepage route','route','/','text','readonly'):field('Slug','slug',values.slug||(tab==='products'?'grid-runner':tab==='categories'?'shoes':tab==='brands'?'aelvo':'footwear-edit'))}${field('Canonical override (optional)','canonical',values.canonical||'','url','placeholder="Inherit self-canonical URL"')}${select('Robots override','robots',['Inherit defaults','index, follow','noindex, follow','noindex, nofollow'],values.robots||'Inherit defaults')}<hr class="divider"><h3>Social sharing</h3>${field('Open Graph title','ogTitle',values.ogTitle||'','text','placeholder="Inherit SEO title"')}${textarea('Open Graph description','ogDescription',values.ogDescription||'','placeholder="Inherit meta description"')}${field('Image ALT text','alt',values.alt||'')}${field('Sharing image (preview only)','image','','file','accept="image/*"')}${tab==='global'?textarea('Social profile URLs','social',values.social||'','placeholder="One URL per line"'):''}<div class="error-text" data-error></div><div class="form-actions">${button('Reset overrides','reset-seo',`data-section="seo-${tab}"`,'btn secondary')}<button class="btn">Save draft</button></div></div><aside class="stack"><div class="card"><h3>Search appearance preview</h3><div class="search-preview"><span class="url">aelvo.example / ${tab==='homepage'?'':E(values.slug||'collection')}</span><h3 id="seo-live-title">${E(title)}</h3><p id="seo-live-description">${E(desc)}</p></div><p class="form-help">An illustration of the effective title and description; search engines may display different text.</p></div><div class="card"><h3>Effective values</h3><div class="status-line">Title ${badge(values.title?'Saved override':'Default')}</div><div class="status-line">Canonical ${badge(values.canonical?'Override':'Self canonical')}</div><div class="status-line">Indexing ${badge(values.robots||'Inherited')}</div></div>${notice('Entity editors and the SEO module will use the same metadata and permissions. All edits here remain demo state.')}</aside></form>`;}
return `${heading('SEO '+(tab==='overview'?'Overview':seoModules.find(m=>m[0]===tab)?.[1]||''),'Content metadata and search visibility, under your control.')}<div class="settings-layout"><nav class="settings-nav" aria-label="SEO modules">${seoModules.map(([id,t])=>link(t,'/admin/seo/'+id,id===tab?'active':'')).join('')}</nav><div>${content}</div></div>`}
const settingsTabs=[['theme','Main theme colours'],['login','Google / Facebook login'],['assistant','AI & support channels'],['general','General'],['checkout','Checkout & COD'],['shipping','Shipping'],['tax','Tax'],['payments','Payment gateways'],['courier','Courier'],['email','Email / SMTP'],['sms','SMS & OTP'],['analytics','Analytics'],['social','Social links'],['backup','Backup / restore']];
function analyticsForm(s,key){const v=s.saved[key]||{};return `<form class="card" data-form="config" data-section="${key}"><h3>Analytics & marketing</h3>${field('GA4 measurement ID','ga',v.ga||'','text','placeholder="G-XXXXXXXXXX"')}${field('Google Tag Manager container','gtm',v.gtm||'','text','placeholder="GTM-XXXXXXX"')}${field('Meta Pixel ID','meta',v.meta||'')}${field('TikTok Pixel ID','tiktok',v.tiktok||'')}${field('Hotjar site ID','hotjar',v.hotjar||'')}${checkbox('Require consent before optional tracking','consent',true)}${checkbox('Enable tracking after configuration','enabled',false)}${notice('No tracking scripts load in this preview. IDs and toggles are draft settings only.')}<div class="form-actions"><button class="btn">Save draft</button></div></form>`}
export function settingsView(s,tab){let v=s.saved['settings-'+tab]||{},body='';if(tab==='theme')body=themeSettings(s);else if(tab==='login')body=loginSettings(s);else if(tab==='assistant')body=aiSettings(s);else if(tab==='general')body=`<h3>Store identity</h3>${field('Store name','name',s.settings.name,'text','required')}<div class="field-grid"><div class="field"><span>Logo</span><div class="upload-tile" style="color:#111;font-weight:750;letter-spacing:6px;font-size:28px">AELVO</div>${field('Replace logo','logo','','file','accept="image/*"')}</div>${field('Favicon','favicon','','file','accept="image/*"')}</div><hr class="divider"><h3>Store defaults</h3><div class="field-grid">${select('Currency','currency',['BDT'],s.settings.currency)}${select('Timezone','timezone',['Asia/Dhaka','UTC','Europe/Bucharest'],s.settings.timezone)}${select('Default language','language',['English','বাংলা'],s.settings.language)}</div><p class="form-help">Store schedules use this timezone.</p><hr class="divider"><h3>Contact details</h3><div class="field-grid">${field('Public phone','phone',v.phone||'','tel','placeholder="Add phone number"')}${field('Support email','email',v.email||'','email','placeholder="Add email address"')}</div>${textarea('Business address','address',v.address||'')}<hr class="divider"><h3>Document numbering</h3><div class="field-grid">${field('Order prefix','orderPrefix',s.settings.orderPrefix)}${field('Invoice prefix','invoicePrefix',s.settings.invoicePrefix)}</div><p class="form-help">Prefixes apply to new documents; historical references stay unchanged.</p>`;
else if(tab==='checkout')body=`<h3>Checkout & COD</h3>${checkbox('Enable guest checkout','guest',v.guest??true)}${checkbox('Enable cash on delivery','cod',v.cod??true)}${select('Advance rule','advance',['No advance','Fixed amount','Percentage','Product / category rule','Customer review rule'],v.advance||'Fixed amount')}${field('Advance amount / percentage','amount',v.amount||'500','number','min="0"')}${textarea('Rule notes','notes',v.notes||'Review high-value and flagged orders before courier booking.')}${notice('Signup needs OTP. A signed-in customer using the current verified account number skips a fresh checkout OTP. Guests and alternate order numbers require verification.')}<p class="form-help">Required advances must be verified before they reduce COD. Saving this form does not change an existing order’s agreed total.</p>`;
else if(tab==='shipping')body=`<h3>Shipping rules</h3><div class="field-grid">${field('Inside Dhaka','inside',v.inside||'80','number','min="0"')}${field('Outside Dhaka','outside',v.outside||'130','number','min="0"')}${field('Sub-area surcharge','subarea',v.subarea||'0','number','min="0"')}${field('Free shipping above (optional)','freeAbove',v.freeAbove||'','number','min="0"')}</div>${select('Calculation','calculation',['Flat by zone','Weight based','Order value based','Product specific'],v.calculation||'Flat by zone')}${textarea('District / weight rule notes','rules',v.rules||'')}`;
else if(tab==='tax')body=`<h3>Tax configuration</h3>${checkbox('Enable configured tax','enabled',v.enabled||false)}${field('Tax label','label',v.label||'Tax')}${field('Configured rate (%)','rate',v.rate||'0','number','min="0" max="100" step="0.01"')}${select('Price treatment','treatment',['Tax exclusive','Tax inclusive'],v.treatment||'Tax exclusive')}${notice('The demo sample is tax-free for arithmetic clarity. These values are configuration placeholders, not advice about applicable tax obligations.')}`;
else if(['payments','courier','email','sms'].includes(tab)){const labels={payments:'Payment gateways',courier:'Steadfast courier',email:'Email / SMTP',sms:'SMS provider & OTP'};body=`<div class="between mb"><h3>${labels[tab]}</h3>${badge('Not connected','outline')}</div>${tab==='email'?field('SMTP host','host',v.host||'','text','placeholder="smtp.example.com"')+field('Port','port',v.port||'587','number','min="1" max="65535"')+select('Encryption','encryption',['TLS','SSL'],v.encryption||'TLS')+field('From email','from',v.from||'','email'):select('Provider','provider',tab==='payments'?['Choose provider','bKash','Nagad','SSLCOMMERZ']:tab==='courier'?['Steadfast']:['BulkSMSBD'],v.provider||(tab==='sms'?'BulkSMSBD':'Choose provider'))}${field(tab==='sms'?'Sender ID':'Account / merchant identifier','identifier',v.identifier||'')}${field('Secret credential','secret','','password','disabled placeholder="Add securely during backend setup"')}${checkbox('Use sandbox mode where available','sandbox',true)}${tab==='sms'?notice('Selected provider: BulkSMSBD (bulksmsbd.net). API key and approved Sender ID will be configured securely on the PHP server. No SMS is sent from this frontend. A delivery failure never bypasses OTP.'):notice('Provider connection tests and real transactions begin in the backend integration phase.')}<div class="mt">${button('View integration checklist','integration-info',`data-type="${tab}"`,'btn secondary')}</div>`;}
else if(tab==='social')body=`<h3>Social links</h3>${['Facebook','Instagram','YouTube','TikTok'].map(l=>field(l,l.toLowerCase(),v[l.toLowerCase()]||'','url','placeholder="https://"')).join('')}`;
else if(tab==='analytics')body=analyticsForm(s,'settings-analytics');
else if(tab==='backup')body=`<h3>Preview snapshot</h3><p class="small muted mb">Download the sample records created in this browser session.</p>${button('Download demo snapshot','backup-download','','btn secondary')}<hr class="divider">${notice('Production backup / restore will require server permissions, verified archives and explicit safeguards. This frontend does not restore a database or include secrets.')}<div class="mt">${link('Open installer preview','/install','text-link')}</div>`;
else body=notice('Select a settings section.');
const form=['analytics','backup'].includes(tab)?body:`<form class="card settings-form" data-form="config" data-section="settings-${tab}">${body}<div class="error-text" data-error></div><div class="form-actions">${button('Reset changes','rerender','','btn secondary')}<button class="btn">Save changes</button></div></form>`;return `${heading('Website Settings','Store identity, defaults and integration configuration.')}<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${settingsTabs.map(([id,t])=>link(t,'/admin/settings/'+id,id===tab?'active':'')).join('')}${link('SEO settings','/admin/seo/global')}</nav><div>${form}</div></div>`}
export function contentEditor(s,id){const p=s.records.pages.find(p=>p.id===id);if(!p)return notice('Page not found.');const text=p.content||'The Footwear Edit\n\nExplore shoes for everyday plans.\n\nFind your next pair\nBrowse the collection and use the product size guide before ordering.';return `${heading('Page Editor',p.name,button('Preview','page-preview',`data-id="${E(id)}"`,'btn secondary'))}${tabs([['content','Content'],['seo/cms','SEO']], 'content','/admin/')}<form class="two-col" data-form="page-editor" data-id="${E(id)}"><div class="card"><div class="field-grid">${field('Page title','name',p.name,'text','required')}${field('URL slug','slug',id,'text','required')}</div><div class="mt">${textarea('Page content','content',text,'style="min-height:340px" required')}</div>${field('Button label','button',p.button||'Explore shoes')}${select('Button destination','destination',['Category: Shoes','Category: Bags','All products'],p.destination||'Category: Shoes')}<div class="error-text" data-error></div><div class="form-actions"><button class="btn secondary" name="intent" value="draft">Save draft</button><button class="btn" name="intent" value="publish">Review & publish demo</button></div></div><aside class="stack"><div class="card"><h3>Publishing</h3><div class="status-line">Current state ${badge(p.status)}</div>${select('Schedule','schedule',['Not scheduled','Schedule later'],'Not scheduled')}${checkbox('Add to footer navigation','footer',false)}<p class="form-help">Drafts stay out of public navigation. Preview changes affect sample content only.</p></div><div class="card"><h3>Page image</h3><img class="inline-image" src="assets/shoe.png" alt="White sneaker on a stone pedestal">${field('Image ALT text','alt',p.alt||'White sneaker on a stone pedestal')}${field('Replace image','image','','file','accept="image/*"')}</div></aside></form>`}
export function bannerEditor(s){const v=s.saved.banner||{};return `${heading('Marketing Banners','Homepage heroes and promotional sections.',link('Welcome popup','/admin/welcome-popup','btn secondary')+link('Coupons','/admin/coupons','btn secondary'))}<div class="settings-layout"><aside class="settings-nav"><a class="active" href="#/admin/banners">Footwear edit ${badge(v.status||'Draft')}</a><a href="#/admin/banners" data-action="banner-select" data-value="Everyday carry">Everyday carry</a><a href="#/admin/banners" data-action="banner-select" data-value="New arrivals">New arrivals</a></aside><form class="card" data-form="banner"><div class="between mb"><h3>Footwear edit</h3>${badge(v.status||'Draft')}</div><div class="banner-preview"><img src="assets/shoe.png" alt="White sneaker on a stone pedestal"><div class="banner-copy"><h2 id="banner-live-heading">${E(v.heading||'STEP INTO EVERYDAY.')}</h2><p id="banner-live-subtitle">${E(v.subtitle||'Explore the footwear edit')}</p><span class="btn small" id="banner-live-button">${E(v.button||'Shop shoes')}</span></div></div><div class="field-grid mt">${field('Heading','heading',v.heading||'STEP INTO EVERYDAY.','text','required data-banner-live="heading"')}${field('Button label','button',v.button||'Shop shoes','text','data-banner-live="button"')}${field('Subtitle','subtitle',v.subtitle||'Explore the footwear edit','text','data-banner-live="subtitle"')}${select('Destination','destination',['Category: Shoes','Category: Bags','All products'],v.destination||'Category: Shoes')}${field('Image ALT text','alt',v.alt||'White sneaker on a stone pedestal')}${field('Replace image','image','','file','accept="image/*"')}${select('Placement','placement',['Homepage hero','Promotional section'],v.placement||'Homepage hero')}${field('Scheduled start (UTC, optional)','start',v.start||'','datetime-local')}</div>${bannerFields(s)}<div class="error-text" data-error></div><div class="form-actions"><button class="btn secondary" name="intent" value="Draft">Save draft</button><button class="btn" name="intent" value="Published">Review & publish demo</button></div><p class="form-help">Publishing a banner does not create or activate a coupon.</p></form></div>`}
export function teamView(s,tab){return teamEditor(s,tab);}
export const installSteps=['Welcome','Requirements','Database','Store details','Super Admin','Business settings','SMTP','Services','Installation','Health check','Finish'];
export function installer(s){const step=s.installerDone?10:s.installerStep;let body='';switch(step){case 0:body=`<p class="eyebrow">AELVO installer</p><h1 class="mt">A considered start.</h1><p class="muted mt">Walk through the planned cPanel installation experience.</p><div class="notice mt">Simulation only. No database connection, schema, credentials or installation lock is created by this frontend.</div>`;break;case 1:body=`<h2>Server requirements</h2>${table(['Requirement','Target','Preview result'],[['PHP','8.1 or newer','Not checked'],['Database','MySQL / MariaDB','Not checked'],['PDO MySQL','Enabled','Not checked'],['Storage / uploads','Writable','Not checked'],['HTTPS','Required for production','Not checked']])}<p class="form-help">The PHP installer will perform real checks on the target hosting server.</p>`;break;case 2:body=`<h2>Database connection</h2><div class="notice mt">Use only the sample values shown. Connection testing belongs to the PHP installer.</div><div class="field-grid mt">${field('Host','host','localhost','text','readonly')}${field('Database name','database','aelvo_demo','text','readonly')}${field('Database user','dbUser','demo_user','text','readonly')}${field('Database password','dbPassword','','password','disabled placeholder="Not collected in preview"')}</div>${button('Preview connection result','installer-connection','','btn secondary mt')}`;break;case 3:body=`<h2>Store details</h2><div class="mt">${field('Store name','store',s.settings.name,'text','required')}${field('Store URL','url','https://aelvo.example','url','required')}${select('Currency','currency',['BDT'])}${select('Timezone','timezone',['Asia/Dhaka','UTC'],'Asia/Dhaka')}</div>`;break;case 4:body=`<h2>First administrator</h2><div class="notice mt">The real installer creates a Super Admin using a securely hashed password. This screen only validates the form.</div><div class="mt">${field('Full name','name','Demo Admin','text','required')}${field('Username','username','demo_admin','text','required')}${field('Email','email','admin@example.com','email','required')}${field('Demo password','password','','password','required minlength="12" placeholder="Use a sample password, 12+ characters"')}${field('Confirm demo password','confirm','','password','required minlength="12"')}</div>`;break;case 5:body=`<h2>Optional business settings</h2><div class="mt">${field('Order prefix','prefix','AEL-')}${field('Invoice prefix','invoice','INV-')}${textarea('Business address','address','','placeholder="Configure later"')}</div>`;break;case 6:body=`<h2>Optional SMTP</h2><div class="mt">${field('SMTP host','host','','text','placeholder="Configure later"')}${field('From email','email','','email')}${field('Secret','secret','','password','disabled placeholder="Set securely in backend setup"')}</div>${notice('Email setup can be skipped and configured later from Admin Settings.')}`;break;case 7:body=`<h2>Optional services</h2>${['Steadfast courier','Payment gateway','SMS provider'].map(l=>`<div class="status-line">${l}${badge('Configure later','outline')}</div>`).join('')}<div class="notice mt">Optional services do not block installation. Working SMS setup is still required before launching signup and OTP-dependent checkout.</div>`;break;case 8:body=`<h2>Review installation</h2><div class="timeline mt">${['Check for an existing installation','Create schema and default settings','Create roles and the Super Admin','Write protected configuration','Create installation lock','Clear temporary secrets'].map(t=>`<div class="timeline-step"><span class="timeline-dot"></span><div>${t}<p>Planned PHP installer action</p></div></div>`).join('')}</div>${notice('The real installer must stop if an existing installation is detected. This simulation changes no server or database.')}`;break;case 9:body=`<h2>Health check preview</h2>${table(['Check','Preview state'],[['Configuration','Simulated'],['Database / tables','Not connected'],['Admin account','Demo only'],['Storage / uploads','Not checked'],['SMTP / courier / payments','Configure later']])}`;break;default:body=`<div class="center"><div class="success-mark">${icon('check')}</div><h2>Installer walkthrough complete.</h2><p class="muted mt">You have reviewed the complete setup flow.</p><div class="flex mt" style="justify-content:center">${link('Go to Admin','/admin')}${link('Visit storefront','/','btn secondary')}</div><p class="form-help mt">Production installation and its security lock are implemented in the PHP phase.</p></div>`;}
return `${previewBar()}<main id="main" class="installer"><header class="installer-header"><a href="#/">${wordmark()}</a>${badge('Installation simulation','outline')}</header><div class="installer-layout"><aside>${installSteps.map((l,i)=>`<div class="install-step ${step===i?'active':i<step?'done':''}"><span class="num">${i<step?'✓':i+1}</span>${l}</div>`).join('')}</aside><form class="card" data-form="installer">${body}<div class="error-text" data-error></div>${step<10?`<div class="form-actions">${step?button('Back','installer-back','','btn secondary'):''}<button class="btn">${step===8?'Simulate installation':step>=5&&step<=7?'Continue / configure later':'Continue'}</button></div>`:''}</form></div></main>`}
